                    "读表时刻不在工单允许窗口 [" + order.windowStart() + ", " + order.windowEnd() + ") 内");
        }
        if (cumulativeMinutes < order.baselineCumulativeMinutes()) {
            throw ApiException.unprocessable("READING_BELOW_BASELINE",
                    "读数低于工单基线（" + order.baselineCumulativeMinutes() + "）");
        }
    }
}

